-- KARISMA ERP - Accounting Karismaerp Master Migration
-- Tanggal: 2026-07-15
-- Scope: struktur dan seed master akun Karismaerp dari data_akun_karismaerp_to_erp.xlsx.
-- Semua tabel baru memakai prefix tbkeu_.
-- Jalankan setelah migration accounting dasar dan runtime selesai.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- =========================================================
-- MIGRATION UP - STRUKTUR BARU
-- =========================================================
CREATE TABLE IF NOT EXISTS `tbkeu_karismaerp_import_batch` (
  `id_batch` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `batch_code` VARCHAR(50) NOT NULL,
  `file_name` VARCHAR(255) NOT NULL,
  `file_hash` VARCHAR(64) DEFAULT NULL,
  `status` ENUM('DRAFT','VALIDATED','APPLIED','FAILED','CANCELLED') NOT NULL DEFAULT 'APPLIED',
  `total_kelompok` INT UNSIGNED NOT NULL DEFAULT 0,
  `total_klasifikasi` INT UNSIGNED NOT NULL DEFAULT 0,
  `total_sub_class` INT UNSIGNED NOT NULL DEFAULT 0,
  `total_kiraan` INT UNSIGNED NOT NULL DEFAULT 0,
  `total_rule_laba_rugi` INT UNSIGNED NOT NULL DEFAULT 0,
  `total_rule_neraca` INT UNSIGNED NOT NULL DEFAULT 0,
  `validation_message` TEXT DEFAULT NULL,
  `created_by` BIGINT DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `applied_by` BIGINT DEFAULT NULL,
  `applied_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_batch`),
  UNIQUE KEY `uk_tbkeu_karismaerp_batch_code` (`batch_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tbkeu_karismaerp_kelompok_jurnal` (
  `id_kelompok_karismaerp` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_batch` BIGINT UNSIGNED DEFAULT NULL,
  `no_kelompok` INT UNSIGNED NOT NULL,
  `kode_kelompok` VARCHAR(20) NOT NULL,
  `nama_kelompok` VARCHAR(150) NOT NULL,
  `keterangan` VARCHAR(255) DEFAULT NULL,
  `is_auto_source` TINYINT(1) NOT NULL DEFAULT 0,
  `simbol` VARCHAR(20) DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_kelompok_karismaerp`),
  UNIQUE KEY `uk_tbkeu_karismaerp_kelompok_no` (`no_kelompok`),
  KEY `idx_tbkeu_karismaerp_kelompok_kode` (`kode_kelompok`),
  KEY `idx_tbkeu_karismaerp_kelompok_batch` (`id_batch`),
  CONSTRAINT `fk_tbkeu_karismaerp_kelompok_batch`
    FOREIGN KEY (`id_batch`) REFERENCES `tbkeu_karismaerp_import_batch` (`id_batch`)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tbkeu_sub_klasifikasi_akun` (
  `id_sub_klasifikasi` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_batch` BIGINT UNSIGNED DEFAULT NULL,
  `kode_sub_klasifikasi` VARCHAR(30) NOT NULL,
  `id_klasifikasi` TINYINT UNSIGNED NOT NULL,
  `nama_sub_klasifikasi` VARCHAR(150) NOT NULL,
  `alias_sub_klasifikasi` VARCHAR(150) DEFAULT NULL,
  `nama_temp_karismaerp` VARCHAR(150) DEFAULT NULL,
  `cashflow_id` VARCHAR(30) DEFAULT NULL,
  `tanggal_edit_source` VARCHAR(50) DEFAULT NULL,
  `id_akun_header` BIGINT UNSIGNED DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_sub_klasifikasi`),
  UNIQUE KEY `uk_tbkeu_sub_klasifikasi_kode` (`kode_sub_klasifikasi`),
  KEY `idx_tbkeu_sub_klasifikasi_klasifikasi` (`id_klasifikasi`),
  KEY `idx_tbkeu_sub_klasifikasi_header` (`id_akun_header`),
  KEY `idx_tbkeu_sub_klasifikasi_batch` (`id_batch`),
  CONSTRAINT `fk_tbkeu_sub_klasifikasi_klasifikasi`
    FOREIGN KEY (`id_klasifikasi`) REFERENCES `tbkeu_klasifikasi_akun` (`id_klasifikasi`)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT `fk_tbkeu_sub_klasifikasi_header`
    FOREIGN KEY (`id_akun_header`) REFERENCES `tbkeu_akun` (`id_akun`)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `fk_tbkeu_sub_klasifikasi_batch`
    FOREIGN KEY (`id_batch`) REFERENCES `tbkeu_karismaerp_import_batch` (`id_batch`)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tbkeu_akun_karismaerp_ref` (
  `id_ref` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_batch` BIGINT UNSIGNED DEFAULT NULL,
  `id_akun` BIGINT UNSIGNED DEFAULT NULL,
  `id_sub_klasifikasi` BIGINT UNSIGNED DEFAULT NULL,
  `kode_kiraan` VARCHAR(30) NOT NULL,
  `kode_rekening_display` VARCHAR(30) DEFAULT NULL,
  `nama_karismaerp` VARCHAR(150) DEFAULT NULL,
  `alias_karismaerp` VARCHAR(150) DEFAULT NULL,
  `temp_nama_karismaerp` VARCHAR(150) DEFAULT NULL,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_ref`),
  UNIQUE KEY `uk_tbkeu_akun_karismaerp_kiraan` (`kode_kiraan`),
  KEY `idx_tbkeu_akun_karismaerp_akun` (`id_akun`),
  KEY `idx_tbkeu_akun_karismaerp_sub` (`id_sub_klasifikasi`),
  KEY `idx_tbkeu_akun_karismaerp_batch` (`id_batch`),
  CONSTRAINT `fk_tbkeu_akun_karismaerp_akun`
    FOREIGN KEY (`id_akun`) REFERENCES `tbkeu_akun` (`id_akun`)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `fk_tbkeu_akun_karismaerp_sub`
    FOREIGN KEY (`id_sub_klasifikasi`) REFERENCES `tbkeu_sub_klasifikasi_akun` (`id_sub_klasifikasi`)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `fk_tbkeu_akun_karismaerp_batch`
    FOREIGN KEY (`id_batch`) REFERENCES `tbkeu_karismaerp_import_batch` (`id_batch`)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `tbkeu_report_rule_akun` (
  `id_rule` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_batch` BIGINT UNSIGNED DEFAULT NULL,
  `statement_type` ENUM('LABA_RUGI','NERACA') NOT NULL,
  `id_akun` BIGINT UNSIGNED DEFAULT NULL,
  `kode_rekening_source` VARCHAR(30) NOT NULL,
  `kode_rekening_normalized` VARCHAR(30) NOT NULL,
  `nama_rekening_source` VARCHAR(150) DEFAULT NULL,
  `klasifikasi_source` VARCHAR(100) DEFAULT NULL,
  `group_source` VARCHAR(150) DEFAULT NULL,
  `bertambah_side` ENUM('DEBIT','KREDIT') NOT NULL,
  `berkurang_side` ENUM('DEBIT','KREDIT') NOT NULL,
  `urutan` INT UNSIGNED NOT NULL DEFAULT 0,
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_rule`),
  UNIQUE KEY `uk_tbkeu_report_rule_statement_code` (`statement_type`, `kode_rekening_normalized`),
  KEY `idx_tbkeu_report_rule_code` (`kode_rekening_normalized`),
  KEY `idx_tbkeu_report_rule_statement_order` (`statement_type`, `urutan`),
  KEY `idx_tbkeu_report_rule_batch` (`id_batch`),
  CONSTRAINT `fk_tbkeu_report_rule_akun`
    FOREIGN KEY (`id_akun`) REFERENCES `tbkeu_akun` (`id_akun`)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT `fk_tbkeu_report_rule_batch`
    FOREIGN KEY (`id_batch`) REFERENCES `tbkeu_karismaerp_import_batch` (`id_batch`)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
-- =========================================================
-- SEED BATCH
-- =========================================================
VALUES ('KARISMAERP-COA-20260715','data_akun_karismaerp_to_erp.xlsx','APPLIED',23,9,36,501,267,230,'Generated from Excel workbook scan on 2026-07-15.',NOW())
ON DUPLICATE KEY UPDATE file_name=VALUES(file_name),status=VALUES(status),total_kelompok=VALUES(total_kelompok),total_klasifikasi=VALUES(total_klasifikasi),total_sub_class=VALUES(total_sub_class),total_kiraan=VALUES(total_kiraan),total_rule_laba_rugi=VALUES(total_rule_laba_rugi),total_rule_neraca=VALUES(total_rule_neraca),validation_message=VALUES(validation_message),applied_at=VALUES(applied_at);
SET @tbkeu_karismaerp_batch_id := (SELECT id_batch FROM tbkeu_karismaerp_import_batch WHERE batch_code = 'KARISMAERP-COA-20260715' LIMIT 1);

-- =========================================================
-- SEED KELOMPOK JURNAL KARISMAERP
-- =========================================================
ON DUPLICATE KEY UPDATE
  id_batch = VALUES(id_batch),
  no_kelompok = VALUES(no_kelompok),
  nama_kelompok = VALUES(nama_kelompok),
  keterangan = VALUES(keterangan),
  is_auto_source = VALUES(is_auto_source),
  simbol = VALUES(simbol),
  is_active = VALUES(is_active);

-- =========================================================
-- SEED JENIS JURNAL DARI KELOMPOK KARISMAERP
-- =========================================================
ON DUPLICATE KEY UPDATE
  nama_jenis_jurnal = VALUES(nama_jenis_jurnal),
  keterangan = VALUES(keterangan),
  is_manual = VALUES(is_manual),
  is_active = VALUES(is_active);

-- =========================================================
-- UPSERT KLASIFIKASI AKUN KARISMAERP
-- =========================================================
ON DUPLICATE KEY UPDATE
  kode_klasifikasi = VALUES(kode_klasifikasi),
  nama_klasifikasi = VALUES(nama_klasifikasi),
  alias_klasifikasi = VALUES(alias_klasifikasi),
  jenis_laporan = VALUES(jenis_laporan),
  saldo_normal = VALUES(saldo_normal),
  urutan = VALUES(urutan),
  is_active = VALUES(is_active);

-- =========================================================
-- UPSERT HEADER KLASIFIKASI PADA COA
-- =========================================================
ON DUPLICATE KEY UPDATE
  nama_akun = VALUES(nama_akun),
  id_klasifikasi = VALUES(id_klasifikasi),
  parent_id = VALUES(parent_id),
  level_akun = VALUES(level_akun),
  saldo_normal = VALUES(saldo_normal),
  tipe_akun = VALUES(tipe_akun),
  tipe_kontrol = VALUES(tipe_kontrol),
  allow_manual_journal = VALUES(allow_manual_journal),
  is_transaction_eligible = VALUES(is_transaction_eligible),
  is_active = VALUES(is_active);

-- =========================================================
-- SEED SUB KLASIFIKASI AKUN KARISMAERP
-- =========================================================
ON DUPLICATE KEY UPDATE
  id_batch = VALUES(id_batch),
  id_klasifikasi = VALUES(id_klasifikasi),
  nama_sub_klasifikasi = VALUES(nama_sub_klasifikasi),
  alias_sub_klasifikasi = VALUES(alias_sub_klasifikasi),
  nama_temp_karismaerp = VALUES(nama_temp_karismaerp),
  cashflow_id = VALUES(cashflow_id),
  tanggal_edit_source = VALUES(tanggal_edit_source),
  is_active = VALUES(is_active);

-- Sub klasifikasi disimpan sebagai master pendukung saja.
-- Rule request 2026-07-15: kode akun 3 digit tidak dibuat sebagai akun COA.
UPDATE tbkeu_sub_klasifikasi_akun
SET id_akun_header = NULL
WHERE id_batch = @tbkeu_karismaerp_batch_id;

-- =========================================================
-- UPSERT AKUN POSTING KIRAAN KARISMAERP PADA COA
-- =========================================================
ON DUPLICATE KEY UPDATE
  nama_akun = VALUES(nama_akun),
  id_klasifikasi = VALUES(id_klasifikasi),
  parent_id = VALUES(parent_id),
  level_akun = VALUES(level_akun),
  saldo_normal = VALUES(saldo_normal),
  tipe_akun = VALUES(tipe_akun),
  tipe_kontrol = VALUES(tipe_kontrol),
  allow_manual_journal = VALUES(allow_manual_journal),
  is_transaction_eligible = VALUES(is_transaction_eligible),
  is_active = VALUES(is_active);

-- =========================================================
-- SEED REFERENSI AKUN KARISMAERP
-- =========================================================
ON DUPLICATE KEY UPDATE
  id_batch = VALUES(id_batch),
  id_akun = VALUES(id_akun),
  id_sub_klasifikasi = VALUES(id_sub_klasifikasi),
  kode_rekening_display = VALUES(kode_rekening_display),
  nama_karismaerp = VALUES(nama_karismaerp),
  alias_karismaerp = VALUES(alias_karismaerp),
  temp_nama_karismaerp = VALUES(temp_nama_karismaerp),
  is_active = VALUES(is_active);

-- Resolve id_akun pada referensi akun Karismaerp setelah COA dibuat.
UPDATE tbkeu_akun_karismaerp_ref ref
JOIN tbkeu_akun a ON a.kode_akun = ref.kode_kiraan
SET ref.id_akun = a.id_akun
WHERE ref.id_batch = @tbkeu_karismaerp_batch_id;

-- Update parent akun POSTING Karismaerp langsung ke header klasifikasi 4 digit.
-- Kode akun 3 digit hanya menjadi sub klasifikasi, bukan akun COA.
UPDATE tbkeu_akun a
JOIN tbkeu_akun_karismaerp_ref ref ON ref.id_akun = a.id_akun
JOIN tbkeu_akun parent ON parent.kode_akun = CAST((a.id_klasifikasi * 1000) AS CHAR)
SET a.parent_id = parent.id_akun, a.level_akun = 2
WHERE ref.id_batch = @tbkeu_karismaerp_batch_id;

-- =========================================================
-- SEED RULE LAPORAN LABA RUGI DAN NERACA KARISMAERP
-- =========================================================
ON DUPLICATE KEY UPDATE
  id_batch = VALUES(id_batch),
  kode_rekening_source = VALUES(kode_rekening_source),
  kode_rekening_normalized = VALUES(kode_rekening_normalized),
  nama_rekening_source = VALUES(nama_rekening_source),
  klasifikasi_source = VALUES(klasifikasi_source),
  group_source = VALUES(group_source),
  bertambah_side = VALUES(bertambah_side),
  berkurang_side = VALUES(berkurang_side),
  urutan = VALUES(urutan),
  is_active = VALUES(is_active);

-- Resolve id_akun pada rule laporan setelah semua akun dibuat.
UPDATE tbkeu_report_rule_akun r
JOIN tbkeu_akun a ON a.kode_akun = r.kode_rekening_normalized
SET r.id_akun = a.id_akun
WHERE r.id_batch = @tbkeu_karismaerp_batch_id;

SET FOREIGN_KEY_CHECKS = 1;

-- =========================================================
-- VERIFICATION
-- =========================================================
SELECT 'tbkeu_karismaerp_kelompok_jurnal' AS table_name, COUNT(*) AS rows_count FROM tbkeu_karismaerp_kelompok_jurnal WHERE id_batch=@tbkeu_karismaerp_batch_id;
SELECT 'tbkeu_sub_klasifikasi_akun' AS table_name, COUNT(*) AS rows_count FROM tbkeu_sub_klasifikasi_akun WHERE id_batch=@tbkeu_karismaerp_batch_id;
SELECT 'tbkeu_akun_karismaerp_ref' AS table_name, COUNT(*) AS rows_count FROM tbkeu_akun_karismaerp_ref WHERE id_batch=@tbkeu_karismaerp_batch_id;
SELECT statement_type, COUNT(*) AS rows_count FROM tbkeu_report_rule_akun WHERE id_batch=@tbkeu_karismaerp_batch_id GROUP BY statement_type;
SELECT COUNT(*) AS report_rules_without_account FROM tbkeu_report_rule_akun r LEFT JOIN tbkeu_akun a ON a.id_akun=r.id_akun WHERE r.id_batch=@tbkeu_karismaerp_batch_id AND a.id_akun IS NULL;
SELECT COUNT(*) AS akun_3_digit_should_be_zero FROM tbkeu_akun WHERE kode_akun REGEXP '^[0-9]{3}$';
SELECT COUNT(*) AS imported_posting_without_parent FROM tbkeu_akun a JOIN tbkeu_akun_karismaerp_ref ref ON ref.id_akun=a.id_akun WHERE ref.id_batch=@tbkeu_karismaerp_batch_id AND a.tipe_akun='POSTING' AND a.parent_id IS NULL;

